//! The list of components: `components.toml`, format 1.
//!
//! One format serves the public list, which is generated by `cargo xtask
//! components` from the release's real assets (sizes and hashes computed,
//! never typed) and embedded in the binary ([`Manifest::embedded`]), and
//! the list a `components_source` folder may carry, which can add
//! components and never change a known one's pins (R22 sections 6.2 and
//! 6.3). The rules are textweaver's (`manifest.rs`, the owner's own code,
//! relicensed under answer 3), with diroxide's fields:
//!
//! - Top level: `format` (1), `diro` (the version the list was cut for),
//!   `generated_by`, and one `[[component]]` table per component.
//! - Per component: `id`, `title`, `kind` (`plugin`, `helper`, `data`),
//!   `version`, `license`, `license_note`, `credit`, `features`,
//!   `needs_tools`, `needs_components`, `protocol`, `min_diro`, `action`
//!   (`place` or `unpack`), `folder` (the id by default), `unpacked_size`.
//! - Per file (`[[component.file]]`): `name`, `size`, `sha256`, `target`
//!   (a triple or `any`), `url` (optional, `https` only), `exec`, `strip`.
//!
//! Checked at load, in words: plain names; sizes above zero; 64 hex
//! digits; `https` only; the pair of id and target unique; at most
//! [`MAX_COMPONENTS`] components and [`MAX_BYTES`] of text. A component
//! that fails is left out with its reason ([`Refusal`]) and the rest load;
//! an unknown field is ignored, so a later list still loads; a `format`
//! newer than this reader's is an error that says a newer diroxide may
//! read it.

use std::collections::BTreeSet;

use serde::Deserialize;

use crate::component::{Action, Component, Kind, Origin};
use crate::error::ComponentError;
use crate::pin::{ANY_TARGET, FilePin, is_plain_name};

/// The list's format this reader knows.
pub const FORMAT: u32 = 1;

/// The list's file name, in the repository and at the top of a source
/// folder.
pub const FILE_NAME: &str = "components.toml";

/// The most components one list may hold.
pub const MAX_COMPONENTS: usize = 200;

/// The most bytes one list may hold.
pub const MAX_BYTES: usize = 1 << 20;

/// The public list of this build, generated by `cargo xtask components`
/// and checked by `cargo xtask regen --check`.
pub const EMBEDDED: &str = include_str!("../components.toml");

/// A component left out of a list, with the reason.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Refusal {
    /// The component's id as the list wrote it (empty when it had none).
    pub id: String,
    /// Why, in words.
    pub reason: String,
}

impl Refusal {
    /// The line said for it: "Left out diro-x: it has no files."
    pub fn line(&self) -> String {
        let id = if self.id.is_empty() {
            "a component"
        } else {
            &self.id
        };
        format!("Left out {id}: {}.", self.reason)
    }
}

/// A list of components, read and checked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Manifest {
    /// The format it was written in.
    pub format: u32,
    /// The diroxide version it was cut for.
    pub diro: String,
    /// What wrote it.
    pub generated_by: String,
    /// The components that passed every check, in the list's order.
    pub components: Vec<Component>,
    /// The components left out, with the reason.
    pub refused: Vec<Refusal>,
}

#[derive(Deserialize)]
struct RawManifest {
    format: Option<i64>,
    #[serde(default)]
    diro: String,
    #[serde(default)]
    generated_by: String,
    #[serde(default)]
    component: Vec<toml::Value>,
}

#[derive(Deserialize)]
struct RawComponent {
    #[serde(default)]
    id: String,
    #[serde(default)]
    title: String,
    #[serde(default)]
    kind: String,
    #[serde(default)]
    version: String,
    #[serde(default)]
    license: String,
    #[serde(default)]
    license_note: String,
    #[serde(default)]
    credit: String,
    #[serde(default)]
    features: Vec<String>,
    #[serde(default)]
    needs_tools: Vec<String>,
    #[serde(default)]
    needs_components: Vec<String>,
    protocol: Option<u32>,
    min_diro: Option<String>,
    #[serde(default)]
    action: String,
    folder: Option<String>,
    #[serde(default)]
    unpacked_size: u64,
    #[serde(default)]
    file: Vec<RawFile>,
}

#[derive(Deserialize)]
struct RawFile {
    #[serde(default)]
    name: String,
    #[serde(default)]
    size: u64,
    #[serde(default)]
    sha256: String,
    target: Option<String>,
    url: Option<String>,
    exec: Option<String>,
    #[serde(default)]
    strip: u32,
}

/// The first line of a parser's message, without the snippet it quotes.
fn first_line(text: &str) -> String {
    text.lines()
        .next()
        .unwrap_or("")
        .trim()
        .trim_end_matches('.')
        .to_owned()
}

/// Whether a text field is fit to say: no control characters, at most
/// 200 characters.
fn sayable(text: &str) -> bool {
    !text.chars().any(char::is_control) && text.chars().count() <= 200
}

impl RawComponent {
    fn into_component(self, origin: Origin) -> Result<Component, String> {
        let kind = match Kind::from_word(&self.kind) {
            Some(kind) => kind,
            None if self.kind.is_empty() => return Err("it has no kind".to_owned()),
            None => return Err(format!("the kind {:?} is not known", self.kind)),
        };
        let action = match self.action.as_str() {
            "" | "place" => Action::Place,
            "unpack" => Action::Unpack,
            "installer" => return Err("installers are not supported yet".to_owned()),
            other => return Err(format!("the action {other:?} is not known")),
        };
        if !is_plain_name(&self.version) {
            return Err("its version is missing or not a plain name".to_owned());
        }
        if self.license.trim().is_empty() {
            return Err("it has no license".to_owned());
        }
        for (field, text) in [
            ("license", &self.license),
            ("license_note", &self.license_note),
            ("credit", &self.credit),
        ] {
            if !sayable(text) {
                return Err(format!("its {field} has control characters or is too long"));
            }
        }
        if !sayable(&self.title) {
            return Err("its title has control characters or is too long".to_owned());
        }
        for (field, names) in [
            ("features", &self.features),
            ("needs_tools", &self.needs_tools),
            ("needs_components", &self.needs_components),
        ] {
            if let Some(bad) = names.iter().find(|n| !is_plain_name(n)) {
                return Err(format!("{field} names {bad:?}, which is not a plain name"));
            }
        }
        if let Some(min) = &self.min_diro
            && !is_plain_name(min)
        {
            return Err("its min_diro is not a plain version".to_owned());
        }
        if action == Action::Unpack && self.unpacked_size == 0 {
            return Err("an unpacked component needs its unpacked_size".to_owned());
        }
        let files = self
            .file
            .into_iter()
            .map(|f| FilePin {
                name: f.name,
                size: f.size,
                sha256: f.sha256,
                target: f.target.unwrap_or_else(|| ANY_TARGET.to_owned()),
                url: f.url,
                exec: f.exec,
                strip: f.strip,
            })
            .collect();
        let component = Component {
            folder: self.folder.unwrap_or_else(|| self.id.clone()),
            id: self.id,
            title: self.title,
            kind,
            version: self.version,
            license: self.license,
            license_note: self.license_note,
            credit: self.credit,
            features: self.features,
            needs_tools: self.needs_tools,
            needs_components: self.needs_components,
            protocol: self.protocol,
            min_diro: self.min_diro,
            action,
            unpacked_size: self.unpacked_size,
            files,
            origin,
        };
        component.check()?;
        Ok(component)
    }
}

/// Reads and checks a list. The list as a whole fails only when it is too
/// large, is not TOML, has no `format`, or has a newer one; a component
/// that fails a check is left out with its reason.
pub fn parse(text: &str, origin: Origin) -> Result<Manifest, ComponentError> {
    if text.len() > MAX_BYTES {
        return Err(ComponentError::Manifest(
            "the components list is larger than 1 MB".to_owned(),
        ));
    }
    let raw: RawManifest = toml::from_str(text).map_err(|e| {
        ComponentError::Manifest(format!(
            "the components list is not valid TOML: {}",
            first_line(&e.to_string())
        ))
    })?;
    let format = match raw.format {
        None => {
            return Err(ComponentError::Manifest(
                "the components list has no format".to_owned(),
            ));
        }
        Some(f) if f > i64::from(FORMAT) => {
            return Err(ComponentError::Manifest(format!(
                "the components list has format {f}; a newer diroxide may read it"
            )));
        }
        Some(f) if f < 1 => {
            return Err(ComponentError::Manifest(format!(
                "the components list has format {f}, which is not known"
            )));
        }
        Some(_) => FORMAT,
    };
    if raw.component.len() > MAX_COMPONENTS {
        return Err(ComponentError::Manifest(format!(
            "the components list has more than {MAX_COMPONENTS} components"
        )));
    }
    let mut components: Vec<Component> = Vec::new();
    let mut refused = Vec::new();
    let mut folders = BTreeSet::new();
    for value in raw.component {
        let id = value
            .get("id")
            .and_then(toml::Value::as_str)
            .unwrap_or("")
            .to_owned();
        let shown = if is_plain_name(&id) {
            id.clone()
        } else {
            String::new()
        };
        let parsed = value
            .try_into::<RawComponent>()
            .map_err(|e| {
                format!(
                    "it is not written as format 1 says: {}",
                    first_line(&e.to_string())
                )
            })
            .and_then(|raw| raw.into_component(origin));
        match parsed {
            Ok(c) if components.iter().any(|k| k.id == c.id) => refused.push(Refusal {
                id: shown,
                reason: "its id is listed twice".to_owned(),
            }),
            Ok(c) if !folders.insert(c.folder.to_ascii_lowercase()) => refused.push(Refusal {
                id: shown,
                reason: "its folder is another component's".to_owned(),
            }),
            Ok(c) => components.push(c),
            Err(reason) => refused.push(Refusal { id: shown, reason }),
        }
    }
    Ok(Manifest {
        format,
        diro: raw.diro,
        generated_by: raw.generated_by,
        components,
        refused,
    })
}

impl Manifest {
    /// An empty list of this format.
    pub fn new(diro: impl Into<String>, generated_by: impl Into<String>) -> Self {
        Self {
            format: FORMAT,
            diro: diro.into(),
            generated_by: generated_by.into(),
            components: Vec::new(),
            refused: Vec::new(),
        }
    }

    /// The public list embedded in this build. A component that failed its
    /// checks is in [`Manifest::refused`]; the tests keep that empty.
    pub fn embedded() -> Self {
        parse(EMBEDDED, Origin::Public).unwrap_or_else(|e| {
            let mut empty = Self::new(env!("CARGO_PKG_VERSION"), "");
            empty.refused.push(Refusal {
                id: String::new(),
                reason: e.to_string(),
            });
            empty
        })
    }

    /// The component with this id.
    pub fn get(&self, id: &str) -> Option<&Component> {
        self.components.iter().find(|c| c.id == id)
    }

    /// Adds the components of a source's list. A component with an id this
    /// list already knows is left out ("a list cannot change its pins"),
    /// and so is one whose folder another component uses; the source's
    /// own refusals come along.
    pub fn add_source(&mut self, source: Manifest) {
        self.refused.extend(source.refused);
        for c in source.components {
            if self.get(&c.id).is_some() {
                self.refused.push(Refusal {
                    id: c.id,
                    reason: "already known; a list cannot change its pins".to_owned(),
                });
            } else if self
                .components
                .iter()
                .any(|k| k.folder.eq_ignore_ascii_case(&c.folder))
            {
                self.refused.push(Refusal {
                    id: c.id,
                    reason: "its folder is another component's".to_owned(),
                });
            } else {
                self.components.push(c);
            }
        }
    }

    /// The list as `components.toml` text, every field in a fixed order,
    /// so the generated file changes only when a component does.
    pub fn to_toml(&self) -> String {
        let mut out = String::new();
        out.push_str("# The components list (plan section 5.14). Generated by cargo xtask\n");
        out.push_str("# components from packaging/components/components.toml and the real\n");
        out.push_str("# assets; do not edit. cargo xtask regen --check fails when it is stale.\n");
        out.push_str(&format!("format = {}\n", self.format));
        out.push_str(&format!("diro = {}\n", quoted(&self.diro)));
        out.push_str(&format!("generated_by = {}\n", quoted(&self.generated_by)));
        for c in &self.components {
            out.push_str("\n[[component]]\n");
            out.push_str(&format!("id = {}\n", quoted(&c.id)));
            out.push_str(&format!("title = {}\n", quoted(&c.title)));
            out.push_str(&format!("kind = {}\n", quoted(c.kind.word())));
            out.push_str(&format!("version = {}\n", quoted(&c.version)));
            out.push_str(&format!("license = {}\n", quoted(&c.license)));
            if !c.license_note.is_empty() {
                out.push_str(&format!("license_note = {}\n", quoted(&c.license_note)));
            }
            if !c.credit.is_empty() {
                out.push_str(&format!("credit = {}\n", quoted(&c.credit)));
            }
            for (key, list) in [
                ("features", &c.features),
                ("needs_tools", &c.needs_tools),
                ("needs_components", &c.needs_components),
            ] {
                if !list.is_empty() {
                    let items: Vec<String> = list.iter().map(|s| quoted(s)).collect();
                    out.push_str(&format!("{key} = [{}]\n", items.join(", ")));
                }
            }
            if let Some(protocol) = c.protocol {
                out.push_str(&format!("protocol = {protocol}\n"));
            }
            if let Some(min) = &c.min_diro {
                out.push_str(&format!("min_diro = {}\n", quoted(min)));
            }
            out.push_str(&format!("action = {}\n", quoted(c.action.word())));
            if c.folder != c.id {
                out.push_str(&format!("folder = {}\n", quoted(&c.folder)));
            }
            if c.unpacked_size > 0 {
                out.push_str(&format!("unpacked_size = {}\n", c.unpacked_size));
            }
            for f in &c.files {
                out.push_str("\n[[component.file]]\n");
                out.push_str(&format!("name = {}\n", quoted(&f.name)));
                out.push_str(&format!("size = {}\n", f.size));
                out.push_str(&format!("sha256 = {}\n", quoted(&f.sha256)));
                out.push_str(&format!("target = {}\n", quoted(&f.target)));
                if let Some(url) = &f.url {
                    out.push_str(&format!("url = {}\n", quoted(url)));
                }
                if let Some(exec) = &f.exec {
                    out.push_str(&format!("exec = {}\n", quoted(exec)));
                }
                if f.strip > 0 {
                    out.push_str(&format!("strip = {}\n", f.strip));
                }
            }
        }
        out
    }
}

/// A TOML basic string: quotes, with `"`, `\` and every control
/// character escaped.
fn quoted(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if c.is_control() => out.push_str(&format!("\\u{:04X}", u32::from(c))),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The body of the `component_manifest` fuzz target: any bytes as a list
/// never panic, every component read passes its own check, and a list
/// written back reads as the same components.
pub fn fuzz_manifest(data: &[u8]) {
    let Ok(text) = std::str::from_utf8(data) else {
        return;
    };
    let Ok(manifest) = parse(text, Origin::OwnSource) else {
        return;
    };
    for c in &manifest.components {
        assert!(c.check().is_ok(), "{c:?}");
    }
    let again = parse(&manifest.to_toml(), Origin::OwnSource);
    assert!(
        again
            .as_ref()
            .is_ok_and(|a| a.components == manifest.components && a.refused.is_empty()),
        "a list written back reads differently: {again:?}"
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pin::sha256_hex;

    fn good() -> String {
        format!(
            r#"
format = 1
diro = "0.1.0-alpha.2"
generated_by = "test"

[[component]]
id = "diro-examples"
title = "Example plugins"
kind = "data"
version = "0.1.0"
license = "Apache-2.0 OR MIT"
features = ["examples"]
action = "unpack"
unpacked_size = 100
something_new = "ignored"

[[component.file]]
name = "diro-examples-0.1.0.zip"
size = 3
sha256 = "{}"
"#,
            sha256_hex(b"abc")
        )
    }

    #[test]
    fn a_good_list_reads_and_writes_back() {
        let m = parse(&good(), Origin::Public).unwrap();
        assert!(m.refused.is_empty(), "{:?}", m.refused);
        let c = m.get("diro-examples").unwrap();
        assert_eq!(c.action, Action::Unpack);
        assert_eq!(c.kind, Kind::Data);
        assert_eq!(c.folder, "diro-examples");
        assert_eq!(c.files[0].target, "any");
        let again = parse(&m.to_toml(), Origin::Public).unwrap();
        assert_eq!(again, m);
        fuzz_manifest(good().as_bytes());
    }

    #[test]
    fn the_embedded_list_is_clean() {
        let m = Manifest::embedded();
        assert!(m.refused.is_empty(), "{:?}", m.refused);
        assert_eq!(
            m.to_toml(),
            EMBEDDED,
            "the embedded list is written as the xtask writes it"
        );
    }

    #[test]
    fn the_whole_list_fails_only_for_its_own_reasons() {
        for (text, words) in [
            ("format = 2", "a newer diroxide may read it"),
            ("format = 0", "not known"),
            ("diro = \"x\"", "no format"),
            ("format = [", "not valid TOML"),
        ] {
            let error = parse(text, Origin::OwnSource).unwrap_err().to_string();
            assert!(error.contains(words), "{error}");
        }
        let big = format!("format = 1\n# {}\n", "x".repeat(MAX_BYTES));
        assert!(parse(&big, Origin::OwnSource).is_err());
        let mut many = String::from("format = 1\n");
        for _ in 0..=MAX_COMPONENTS {
            many.push_str("[[component]]\nid = \"a\"\n");
        }
        assert!(
            parse(&many, Origin::OwnSource)
                .unwrap_err()
                .to_string()
                .contains("more than 200")
        );
    }

    #[test]
    fn each_bad_component_is_left_out_with_its_reason() {
        let base = good();
        let cases = [
            (
                "kind = \"data\"",
                "kind = \"theme\"",
                "kind \"theme\" is not known",
            ),
            ("kind = \"data\"\n", "", "no kind"),
            (
                "action = \"unpack\"",
                "action = \"installer\"",
                "installers are not supported yet",
            ),
            (
                "action = \"unpack\"",
                "action = \"run\"",
                "action \"run\" is not known",
            ),
            ("version = \"0.1.0\"", "version = \"../1\"", "version"),
            (
                "license = \"Apache-2.0 OR MIT\"",
                "license = \" \"",
                "no license",
            ),
            ("unpacked_size = 100", "unpacked_size = 0", "unpacked_size"),
            (
                "name = \"diro-examples-0.1.0.zip\"",
                "name = \"../up.zip\"",
                "not a plain name",
            ),
            (
                "name = \"diro-examples-0.1.0.zip\"",
                "name = \"nul.zip\"",
                "not a plain name",
            ),
            (
                "name = \"diro-examples-0.1.0.zip\"",
                "name = \"a:b.zip\"",
                "not a plain name",
            ),
            ("size = 3", "size = 0", "no size"),
            ("size = 3", "size = -1", "not written as format 1 says"),
            (
                "features = [\"examples\"]",
                "features = [\"a b\"]",
                "not a plain name",
            ),
            (
                "id = \"diro-examples\"",
                "id = \"diro examples\"",
                "not a plain name",
            ),
            (
                "size = 3",
                "size = 3\nurl = \"http://example.invalid/a\"",
                "not https",
            ),
            (
                "title = \"Example plugins\"",
                "title = \"a\\u0007b\"",
                "control characters",
            ),
        ];
        for (from, to, words) in cases {
            let text = base.replacen(from, to, 1);
            assert_ne!(text, base, "{from}");
            let m = parse(&text, Origin::OwnSource).unwrap();
            assert!(m.components.is_empty(), "{to}");
            assert_eq!(m.refused.len(), 1, "{to}");
            assert!(
                m.refused[0].reason.contains(words),
                "{}: {}",
                to,
                m.refused[0].reason
            );
        }
        let hash = sha256_hex(b"abc").to_uppercase();
        let m = parse(&base.replace(&sha256_hex(b"abc"), &hash), Origin::OwnSource).unwrap();
        assert!(m.refused[0].reason.contains("SHA-256"));
    }

    #[test]
    fn a_source_adds_and_never_replaces() {
        let mut public = parse(&good(), Origin::Public).unwrap();
        let mut source = parse(&good(), Origin::OwnSource).unwrap();
        let mut other = source.components[0].clone();
        other.id = "diro-other".into();
        other.folder = "diro-other".into();
        source.components.push(other);
        public.add_source(source);
        assert_eq!(public.components.len(), 2);
        assert_eq!(public.get("diro-other").unwrap().origin, Origin::OwnSource);
        assert_eq!(public.get("diro-examples").unwrap().origin, Origin::Public);
        assert_eq!(
            public.refused[0].line(),
            "Left out diro-examples: already known; a list cannot change its pins."
        );
        let twice = format!(
            "{}\n{}",
            good(),
            good()
                .replace("format = 1", "")
                .replace("diro =", "#")
                .replace("generated_by =", "#")
        );
        let m = parse(&twice, Origin::OwnSource).unwrap();
        assert_eq!(m.components.len(), 1);
        assert_eq!(m.refused[0].reason, "its id is listed twice");
    }

    /// The fixture lists, which are also the fuzz target's seeds: each
    /// says on its first line what reading it gives.
    #[test]
    fn the_fixture_lists_say_what_they_expect() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/components/manifests");
        let mut seen = 0;
        for item in std::fs::read_dir(&dir).unwrap() {
            let path = item.unwrap().path();
            let name = path.display().to_string();
            let text = std::fs::read_to_string(&path).unwrap();
            fuzz_manifest(text.as_bytes());
            let first = text.lines().next().unwrap();
            let read = parse(&text, Origin::OwnSource);
            if let Some(words) = first.strip_prefix("# expect-error: ") {
                let error = read.unwrap_err().to_string();
                assert!(error.contains(words), "{name}: {error}");
            } else if first == "# expect: ok" {
                let m = read.unwrap();
                assert!(m.refused.is_empty(), "{name}: {:?}", m.refused);
                assert!(!m.components.is_empty(), "{name}");
            } else {
                let words = first.strip_prefix("# expect: ").expect("an expect line");
                let m = read.unwrap();
                assert_eq!(m.refused.len(), 1, "{name}: {:?}", m.refused);
                assert!(
                    m.refused[0].reason.contains(words),
                    "{name}: {:?}",
                    m.refused
                );
            }
            seen += 1;
        }
        assert!(seen >= 15, "{seen} fixtures");
    }

    #[test]
    fn strings_are_escaped() {
        assert_eq!(quoted("a\"b\\c\nd\u{1}"), "\"a\\\"b\\\\c\\nd\\u0001\"");
        let mut m = parse(&good(), Origin::Public).unwrap();
        m.components[0].credit = "Ada \"Example\" \\ caf\u{e9}".into();
        let again = parse(&m.to_toml(), Origin::Public).unwrap();
        assert_eq!(again.components[0].credit, m.components[0].credit);
    }
}
